from json_min import minify_json
from jsmin import minify_js
from svg_min import minify_svg
from xml_min import minify as minify_xml

EXTENSIONS = {
    'asp':'text/asp', 'css':'text/css', 'ejs':'text/x-ejs-template',
    'gohtml':'text/x-go-template', 'handlebars':'text/x-handlebars-template',
    'htm':'text/html', 'html':'text/html', 'js':'application/javascript',
    'json':'application/json', 'mjs':'application/javascript',
    'mustache':'text/x-mustache-template', 'php':'application/x-httpd-php',
    'rss':'application/rss+xml', 'svg':'image/svg+xml', 'tmpl':'text/x-template',
    'webmanifest':'application/manifest+json', 'xhtml':'application/xhtml+xml', 'xml':'text/xml',
}

def canonical_type(value):
    """Resolve a CLI type name, extension, or MIME type to a MIME type."""
    value = (value or '').strip().lower()
    if '/' not in value:
        key = value.removeprefix('.')
        if key in EXTENSIONS:
            return EXTENSIONS[key]
    return value

def minify(data, media_type, options=None):
    """Minify decoded text according to a type or MIME type string."""
    options = options or {}
    mime = canonical_type(media_type).split(';', 1)[0].strip()
    if mime == 'text/css':
        return minify_css(data, int(options.get('css-precision', 0) or 0), int(options.get('css-version', 0) or 0))
    if mime in ('application/javascript', 'text/javascript', 'application/x-javascript', 'text/ecmascript', 'application/ecmascript'):
        return minify_js(data, options)
    if mime.endswith('/json') or mime.endswith('+json') or mime == 'application/manifest+json':
        return minify_json(data, bool(options.get('json-keep-numbers')), int(options.get('json-precision', 0) or 0))
    if mime == 'image/svg+xml':
        return minify_svg(data, bool(options.get('svg-keep-comments')), int(options.get('svg-precision', 0) or 0), options.get('svg-keep-namespaces'))
    if mime.endswith('/xml') or mime.endswith('+xml'):
        return minify_xml(data, bool(options.get('xml-keep-whitespace')))
    if mime in ('text/html', 'application/xhtml+xml', 'text/x-template', 'text/asp', 'text/x-ejs-template', 'text/x-go-template', 'text/x-handlebars-template', 'text/x-mustache-template'):
        try:
